
const categories=['Cadastro futuro','Liberação veicular','E-mail/Pendência','Equipamento/Manutenção','Ocorrência','Acesso','Solicitação de Vídeo/Imagens','Solicitação de Relatório','Outros'];let items=[],handovers=[];const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=s=>new Date(s).toLocaleString('pt-BR',{timeZone:MOPShift.zone});
const STORAGE_KEY='mop_demo_offline_v1';
if(typeof document!=='undefined')document.addEventListener('focusin',event=>{const field=event.target;if(field.matches('textarea,input[type=text],input[type=search]')){field.spellcheck=true;field.lang='pt-BR';}},true);
function readStore(){if(!window.mopDesktop)throw Error('Abra o MOP pelo aplicativo ou por npm start no projeto.');const s=window.mopDesktop.read();if(ensureProtocols(s))writeStore(s);return s}
function writeStore(s){window.mopDesktop.write(s)}
function field(d,k,limit,required=false){let v=d[k]??'';if(typeof v!=='string'||v.length>limit||(required&&!v.trim()))throw Error(`Campo ${k} inválido ou vazio`);return v.trim()}
const request=async(url,method='GET',body)=>{let s=readStore(),timestamp=new Date().toISOString(),shift=MOPShift.at(timestamp);const editing=url.match(/^\/api\/items\/(\d+)\//);if(method!=='GET'&&editing){const previous=items.find(x=>x.id===Number(editing[1])),current=s.items.find(x=>x.id===Number(editing[1]));if(previous&&JSON.stringify(previous)!==JSON.stringify(current))throw Error('Este registro mudou em outra máquina. Recarregue os registros e confira a alteração antes de salvar.');}if(method==='GET'){if(url==='/api/items')return s.items.filter(x=>window.mopShowDeleted||!x.deleted_at).sort((a,b)=>(a.status==='Resolvido')-(b.status==='Resolvido')||({Urgente:0,Atenção:1,Normal:2}[a.priority]-{Urgente:0,Atenção:1,Normal:2}[b.priority])||b.updated_at.localeCompare(a.updated_at));if(url==='/api/handovers')return [...s.handovers].reverse().slice(0,30);let m=url.match(/^\/api\/items\/(\d+)\/events$/);if(m)return s.events.filter(e=>e.item_id===Number(m[1])).reverse();throw Error('Ação desconhecida')}
if(url==='/api/items'){let d=body||{},v={};for(let [k,n,req] of [['condo',100,true],['company',100,false],['category',80,true],['subject',160,true],['description',3000,true],['action_taken',3000,false],['next_action',1000,false],['source',100,false],['reference',200,false],['created_by',100,true]])v[k]=field(d,k,n,req);Object.assign(v,planningValues(d,v.category));v.status=field(d,'status',50)||'Pendente';v.priority=field(d,'priority',30)||'Normal';if(!categories.includes(v.category)||!['Pendente','Em andamento','Aguardando resposta','Aguardando manutenção','Resolvido'].includes(v.status)||!['Normal','Atenção','Urgente'].includes(v.priority))throw Error('Seleção inválida');let id=s.nextItem++;v.protocol=createProtocol(timestamp,new Set(s.items.map(x=>x.protocol)));s.items.push({id,created_at:timestamp,created_shift:shift,updated_shift:shift,updated_at:timestamp,...v,updated_by:v.created_by});s.events.push({id:s.nextEvent++,item_id:id,at:timestamp,shift,actor:v.created_by,kind:'Criado',detail:'Registro criado: '+v.status});writeStore(s);return {id}}
let deletion=url.match(/^\/api\/items\/(\d+)\/delete$/);if(deletion){if(window.mopAccount?.role!=="admin")throw Error("Somente administradores podem remover registros.");const id=Number(deletion[1]),x=s.items.find(i=>i.id===id);if(!x||x.deleted_at)throw Error("Registro indisponível ou já removido.");const reason=field(body,"reason",1000,true);x.deleted_at=timestamp;x.deleted_reason=reason;x.deleted_by=window.mopAccount.email;x.updated_at=timestamp;x.updated_by=window.mopAccount.email;s.events.push({id:s.nextEvent++,item_id:id,at:timestamp,shift,actor:window.mopAccount.email,kind:"Removido pelo administrador",detail:"Registro removido. Motivo: "+reason});writeStore(s);return {ok:true}}
let planning=url.match(/^\/api\/items\/(\d+)\/planning$/);if(planning){const id=Number(planning[1]),x=s.items.find(i=>i.id===id);if(!x||x.status==='Resolvido')throw Error('O planejamento só pode ser alterado em registros abertos.');const actor=field(body,'actor',100,true),values=planningValues(body,x.category),previous={};for(const k of planningKeys)previous[k]=x[k]||'';Object.assign(x,values,{updated_at:timestamp,updated_shift:shift,updated_by:actor});s.events.push({id:s.nextEvent++,item_id:id,at:timestamp,shift,actor,kind:'Planejamento atualizado',detail:'Prazo: '+(values.deadline||'não definido')+' | Responsável: '+(values.assignee||'não definido'),planning_before:previous,planning_after:values});writeStore(s);return {ok:true}}
let correction=url.match(/^\/api\/items\/(\d+)\/resolved-edit$/);if(correction){const id=Number(correction[1]),x=s.items.find(i=>i.id===id);if(!x||x.status!=='Resolvido')throw Error('Esta edição é permitida apenas para registros resolvidos.');const d=body||{};if(Object.keys(d).some(k=>!['note','action_taken','next_action'].includes(k)))throw Error('Somente nota, ação realizada e próxima ação podem ser editadas.');const note=field(d,'note',1500,true),action=field(d,'action_taken',3000),next=field(d,'next_action',1000);const before={action_taken:x.action_taken,next_action:x.next_action};Object.assign(x,{action_taken:action,next_action:next,updated_at:timestamp,updated_shift:shift,updated_by:window.mopAccount?.display_name||'Operador de teste'});s.events.push({id:s.nextEvent++,item_id:id,at:timestamp,shift,actor:window.mopAccount?.display_name||'Operador de teste',kind:'Correção após resolução',detail:note+' | Status mantido: Resolvido',before,after:{action_taken:action,next_action:next}});writeStore(s);return {ok:true}}
let m=url.match(/^\/api\/items\/(\d+)\/update$/);if(m){let id=Number(m[1]),x=s.items.find(i=>i.id===id);if(!x)throw Error('Registro não encontrado');if(x.status==='Resolvido')throw Error('Registro resolvido: disponível apenas para consulta do histórico.');let d=body||{},actor=window.mopAccount?.display_name||field(d,'actor',100,true),note=field(d,'note',1500,true),status=field(d,'status',50)||x.status,action=field(d,'action_taken',3000),next=field(d,'next_action',1000);if(!['Pendente','Em andamento','Aguardando resposta','Aguardando manutenção','Resolvido'].includes(status))throw Error('Status inválido');const before={action_taken:x.action_taken,next_action:x.next_action};Object.assign(x,{updated_at:timestamp,updated_shift:shift,updated_by:actor,status,action_taken:action,next_action:next});s.events.push({id:s.nextEvent++,item_id:id,at:timestamp,shift,actor,kind:'Atualizado',detail:note+' | Status: '+status,before,after:{action_taken:action,next_action:next}});writeStore(s);return {ok:true}}
if(url==='/api/handovers'){let d=body||{},incoming=field(d,'incoming',100,true),outgoing=field(d,'outgoing',100,true),note=field(d,'note',1500),ids=s.items.filter(i=>i.status!=='Resolvido').map(i=>i.id);let id=s.nextHandover++;s.handovers.push({id,at:timestamp,shift,incoming,outgoing,note,critical_protocols:d.critical_protocols||[],open_ids:JSON.stringify(ids),snapshot:s.items.filter(i=>i.status!=='Resolvido').map(i=>JSON.parse(JSON.stringify(i)))});writeStore(s);return {id,count:ids.length}}throw Error('Ação desconhecida')};
let toastTimer;function toast(msg,error=false){clearTimeout(toastTimer);$('#message').innerHTML=`<div class="notice ${error?'error':''}">${esc(msg)}</div>`;if(!error)toastTimer=setTimeout(()=>$('#message').innerHTML='',10000)}
function tab(name){document.querySelectorAll('main section').forEach(x=>x.classList.toggle('hidden',x.id!==name));document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));if(name==='records')renderList();if(name==='overview')renderDeadlines();if(name==='calendar')renderCalendar();const parent=$('.breadcrumb-parent');if(parent){parent.textContent=name==='calendar'?'Ferramentas':name==='about'?'':'Central operacional';parent.hidden=name==='about';}const separator=$('.breadcrumb-separator');if(separator)separator.hidden=name==='about';const crumb=$('#breadcrumb');if(crumb)crumb.textContent={overview:'Início',records:'Registros',new:'Novo registro',handover:'Passagem de turno',calendar:'Calendario',about:'Sobre'}[name];window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
function short(x){return `<div class="item ${x.status==='Resolvido'?'resolved':x.priority==='Urgente'?'urgent':x.priority==='Atenção'?'attention':''}"><div class="row"><strong>#${x.id} · ${esc(x.subject)}</strong><span class="tag">${esc(x.status)}</span></div><p>${esc(x.condo)} · ${esc(x.category)} · ${esc(x.priority)}</p>${planningSummary(x)}<p><b>Próxima ação:</b> ${esc(x.next_action||'Não registrada')}</p><small>Atualizado por ${esc(x.updated_by)} em ${fmt(x.updated_at)}</small></div>`}
function compactPending(x){const late=deadlineBucket(x)==='late';return `<details class="compact-pending"><summary><span class="tag ${x.priority==='Urgente'?'urgent-tag':''}">${esc(x.priority||'Normal')}</span><span><b>${esc(x.condo)} · ${esc(x.subject)}</b><small>${esc(x.next_action||'Próxima ação não registrada')}</small></span><span class="due-label ${late?'due-late':''}">${late?'Atrasado · ':''}${esc(displayLocal(x.deadline))}</span></summary><div class="pending-detail"><p><b>Status:</b> ${esc(x.status)} · <b>Responsável:</b> ${esc(x.assignee||'Não definido')}</p><p>${esc(x.description||'')}</p><p><b>Ação realizada:</b> ${esc(x.action_taken||'—')}</p><small>Registro #${x.id} · ${esc(x.protocol||'Sem protocolo')}</small></div></details>`}
function snapshotHistory(h){if(!Array.isArray(h.snapshot))return '<p class="muted">Passagem antiga: não há retrato das informações da época. IDs recebidos: '+esc(JSON.parse(h.open_ids).map(id=>'#'+id).join(', ')||'nenhum')+'.</p>';return h.snapshot.length?'<p class="muted">Informações preservadas no momento do recebimento.</p>'+h.snapshot.map(x=>`<div class="snapshot-item"><strong>#${x.id} · ${esc(x.condo)} · ${esc(x.subject)}</strong><p><b>Status na passagem:</b> ${esc(x.status)}<br><b>Próxima ação:</b> ${esc(x.next_action||'—')}<br><b>Prazo:</b> ${esc(displayLocal(x.deadline))}<br><b>Responsável:</b> ${esc(x.assignee||'Não definido')}</p><small>${esc(x.protocol||'')}</small></div>`).join(''):'<p class="muted">Nenhuma pendência no momento do recebimento.</p>'}
function handoverCard(h){return `<div class="item"><strong>${esc(fmt(h.at))} · ${esc(shiftLabel(h.shift,h.at))}</strong><p>${esc(h.outgoing)} → <b>${esc(h.incoming)}</b></p><small>${JSON.parse(h.open_ids).length} pendência(s) recebida(s)</small><p>${esc(h.note||'Sem recado adicional')}</p><details><summary>Consultar retrato da passagem</summary>${snapshotHistory(h)}</details></div>`}
function renderHandover(open){const now=new Date(),ordered=[...open].sort((a,b)=>(b.priority==='Urgente')-(a.priority==='Urgente')||(deadlineBucket(b,now)==='late')-(deadlineBucket(a,now)==='late')||(a.deadline||'9999').localeCompare(b.deadline||'9999'));$('#handoverSummary').innerHTML=[['Pendências abertas',open.length],['Urgentes',open.filter(x=>x.priority==='Urgente').length],['Atrasadas',open.filter(x=>deadlineBucket(x,now)==='late').length]].map(([label,n])=>'<div><strong>'+n+'</strong><span>'+label+'</span></div>').join('');$('#handoverItems').innerHTML=ordered.length?ordered.map(compactPending).join(''):'<div class="empty">Nenhuma pendência aberta.</div>';const all=[...readStore().handovers].sort((a,b)=>b.id-a.id);$('#handoverHistory').innerHTML=all.length?handoverCard(all[0])+(all.length>1?'<details><summary>Consultar passagens anteriores ('+(all.length-1)+')</summary>'+all.slice(1).map(handoverCard).join('')+'</details>':''):'<div class="empty">Nenhuma passagem registrada.</div>'}
function render(){updateShiftIndicator();let open=items.filter(x=>x.status!=='Resolvido');$('#stats').innerHTML=[['Abertos',open.length],['Urgentes',open.filter(x=>x.priority==='Urgente').length],['Aguardando resposta/manutenção',open.filter(x=>x.status.startsWith('Aguardando')).length],['Resolvidos',items.length-open.length]].map(([a,b])=>`<div class="card"><small>${a}</small><strong>${b}</strong></div>`).join('');$('#highlights').innerHTML=open.length?open.slice(0,8).map(short).join(''):'<div class="empty">Nenhuma pendência aberta.</div>';renderHandover(open);renderList();renderDeadlines();if(!$('#calendar').classList.contains('hidden'))renderCalendar()}
function resolvedEditor(x){return `<div class="actions"><button type="button" class="edit-resolved" data-id="${x.id}" aria-expanded="false" aria-controls="resolved-form-${x.id}">Editar Registro</button></div><form id="resolved-form-${x.id}" class="resolved-edit hidden" data-id="${x.id}" novalidate><p class="muted">O status permanece Resolvido. A correção será acrescentada ao histórico com a identificação da conta autenticada.</p><label for="correction-note-${x.id}">Nota de Atualização *</label><textarea id="correction-note-${x.id}" name="note" maxlength="1500" required placeholder="Informe a correção ou observação adicional."></textarea><label for="correction-action-${x.id}">Ação realizada</label><textarea id="correction-action-${x.id}" name="action_taken" maxlength="3000">${esc(x.action_taken)}</textarea><label for="correction-next-${x.id}">Próxima ação</label><textarea id="correction-next-${x.id}" name="next_action" maxlength="1000">${esc(x.next_action)}</textarea><div class="correction-status" role="alert"></div><div class="actions"><button type="button" class="save-correction primary">Salvar alterações</button><button type="button" class="cancel-correction">Cancelar</button></div></form>`}
function renderList(){let q=$('#search').value.toLocaleLowerCase(),f=$('#filter').value;let data=items.filter(x=>(window.mopShowDeleted||!x.deleted_at)&&(f==='all'||(f==='open'?x.status!=='Resolvido':x.status===f))&&[x.subject,x.condo,x.company,x.reference,x.category,x.protocol||'',x.email_subject||'',x.email_sender||''].some(v=>v.toLocaleLowerCase().includes(q)));$('#list').innerHTML=data.length?data.map(x=>`<details class="item record-card ${x.status==='Resolvido'?'resolved':x.priority==='Urgente'?'urgent':x.priority==='Atenção'?'attention':''}"><summary class="record-summary"><span class="record-heading"><strong>#${x.id} · ${esc(x.subject)}</strong><small>${esc(x.condo)} · ${esc(x.category)}</small></span><span class="record-priority tag ${x.priority==='Urgente'?'urgent-tag':''}">${esc(x.priority)}</span><span class="quick-status-wrap"><select class="quick-status status-${x.status.toLowerCase().replaceAll(' ','-')}" data-id="${x.id}" aria-label="Alterar status do registro #${x.id}">${['Pendente','Em andamento','Aguardando resposta','Aguardando manutenção','Resolvido'].map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select></span><span class="record-chevron" aria-hidden="true">⌄</span></summary><div class="record-body"><p><b>Empresa:</b> ${esc(x.company||'Não informada')}</p><p>${esc(x.description)}</p><p><b>Ação realizada:</b> ${esc(x.action_taken||'—')}<br><b>Próxima ação:</b> ${esc(x.next_action||'—')}</p><small>Criado por ${esc(x.created_by)} em ${fmt(x.created_at)} · Atualizado por ${esc(x.updated_by)} em ${fmt(x.updated_at)}<br>Turno de criação: ${esc(shiftLabel(x.created_shift,x.created_at))} · Última atualização: ${esc(shiftLabel(x.updated_shift,x.updated_at))}<br>Origem: ${esc(x.source||'—')} · Referência: ${esc(x.reference||'—')}</small>${planningSummary(x)}${x.status==='Resolvido'?resolvedEditor(x):planningEditor(x)}${x.status==='Resolvido'?'':`<details class="update-section"><summary>Atualizar registro</summary><p class="muted">Informe uma nova atualização. Status, ação realizada e próxima ação em branco mantêm os valores atuais.</p><form class="update" data-id="${x.id}" novalidate><p class="authenticated-author">Atualização registrada como <strong>${esc(window.mopAccount?.display_name||'usuário autenticado')}</strong>.</p><label for="field-19-${x.id}">Nota da atualização *</label><textarea id="field-19-${x.id}" name="note" required maxlength="1500"></textarea><label for="field-20-${x.id}">Ação realizada</label><textarea id="field-20-${x.id}" name="action_taken" maxlength="3000"></textarea><label for="field-21-${x.id}">Próxima ação</label><textarea id="field-21-${x.id}" name="next_action" maxlength="1000"></textarea><div class="update-status" role="alert" aria-live="assertive"></div><button type="button" class="save-update">Registrar atualização</button></form></details>`}<details class="history-section" data-id="${x.id}"><summary>Consultar histórico</summary><div class="history" data-id="${x.id}"></div></details></div></details>`).join(''):'<div class="empty">Nenhum registro encontrado.</div>'}
$('#list').addEventListener('pointerdown',e=>{if(e.target.closest('.quick-status'))e.stopPropagation();});
$('#list').addEventListener('click',e=>{if(e.target.closest('.quick-status'))e.stopPropagation();});
$('#list').addEventListener('change',e=>{const select=e.target.closest('.quick-status');if(!select)return;e.stopPropagation();const id=Number(select.dataset.id),item=items.find(x=>x.id===id),previous=item?.status,next=select.value;if(!item||next===previous)return;if(next==='Resolvido'&&!confirm('Marcar este registro como Resolvido? Esta alteração será registrada no histórico.')){select.value=previous;select.blur();return;}select.disabled=true;select.blur();setTimeout(async()=>{try{await request('/api/items/'+id+'/update','POST',{actor:window.mopAccount?.display_name||'Operador',note:'Status alterado de '+previous+' para '+next+'.',status:next,action_taken:item.action_taken||'',next_action:item.next_action||''});await refresh();toast('Status atualizado para '+next+'.');}catch(err){const current=document.querySelector('.quick-status[data-id="'+id+'"]');if(current){current.value=previous;current.disabled=false;}toast(err.message||String(err),true);}finally{const current=document.querySelector('.quick-status[data-id="'+id+'"]');if(current)current.disabled=false;}},80);});
$('#list').addEventListener('toggle',e=>{const section=e.target;if(!section.open)return;if(section.classList.contains('history-section'))historyFor(Number(section.dataset.id));if(section.classList.contains('update-section')){const form=section.querySelector('form');form.reset();form.querySelector('.update-status').innerHTML=''}},true);
async function historyFor(id){try{let ev=await request(`/api/items/${id}/events`);document.querySelector(`.history[data-id="${id}"]`).innerHTML=ev.map(e=>`<p><small>${fmt(e.at)} · ${esc(e.actor)} · ${esc(e.kind)} · ${esc(shiftLabel(e.shift,e.at))}</small><br>${esc(e.detail)}${planningAudit(e)}${e.before&&e.after?`<br><small>Ação anterior: ${esc(e.before.action_taken||'—')} · Ação corrigida: ${esc(e.after.action_taken||'—')}<br>Próxima ação anterior: ${esc(e.before.next_action||'—')} · Próxima ação corrigida: ${esc(e.after.next_action||'—')}</small>`:''}</p>`).join('')}catch(e){toast(e.message,true)}}
async function refresh(strict=false){try{[items,handovers]=await Promise.all([request('/api/items'),request('/api/handovers')]);render()}catch(e){if(strict)throw e;toast(e.message,true)}}
$('#search').oninput=renderList;$('#filter').onchange=renderList;
function formValues(form){const d={};for(const el of form.elements)if(el.name)d[el.name]=el.value;return d}
let saving=false;
async function saveRecord(e){if(e)e.preventDefault();if(saving)return;const form=$('#newForm'),button=$('#saveRecord'),status=$('#saveStatus');try{const d=formValues(form);const required={condo:'Condomínio',category:'Categoria',subject:'Assunto',created_by:'Operador',description:'Descrição'};const missing=Object.keys(required).filter(k=>!String(d[k]||'').trim());if(missing.length){status.innerHTML='<div class="notice error">Preencha: '+missing.map(k=>required[k]).join(', ')+'.</div>';form.elements.namedItem(missing[0]).focus();return}if(!form.checkValidity()){form.querySelectorAll(':invalid').forEach(el=>{const section=el.closest('details');if(section)section.open=true});status.innerHTML='<div class="notice error">Confira os campos destacados e os limites de caracteres.</div>';form.reportValidity();return}saving=true;button.disabled=true;status.innerHTML='<div class="notice">Gravando…</div>';const result=await request('/api/items','POST',d);const saved=await request('/api/items');if(!saved.some(x=>x.id===result.id))throw Error('Não foi possível confirmar o registro gravado.');items=saved;handovers=await request('/api/handovers');$('#search').value='';$('#filter').value='open';render();form.reset();form.querySelectorAll('details').forEach(el=>el.open=false);syncRequestFields(form);status.innerHTML='';tab('records');toast('Registro #'+result.id+' salvo e conferido no banco local.');$('#message').scrollIntoView({block:'nearest'})}catch(err){status.innerHTML='<div class="notice error">'+esc(err.message||String(err))+'</div>';toast(err.message||String(err),true)}finally{saving=false;button.disabled=false}}
$('#newForm').onsubmit=saveRecord;$('#saveRecord').onclick=saveRecord;
const updatesInProgress=new Set();
async function updateRecord(form){
 const id=Number(form.dataset.id);if(updatesInProgress.has(id))return;
 const button=form.querySelector('.save-update'),feedback=form.querySelector('.update-status');
 try{
 const d=formValues(form),current=readStore().items.find(x=>x.id===id);if(!current)throw Error('Registro não encontrado');for(const k of ['status','action_taken','next_action'])if(!String(d[k]||'').trim())d[k]=current[k];const missing=[];if(!String(d.actor||'').trim())missing.push('Operador');if(!String(d.note||'').trim())missing.push('Nota da atualização');
 if(missing.length){feedback.innerHTML='<div class="notice error">Preencha: '+missing.join(' e ')+'.</div>';form.elements.namedItem(!String(d.actor||'').trim()?'actor':'note').focus();return}
 if(!form.checkValidity()){feedback.innerHTML='<div class="notice error">Confira os limites dos campos antes de salvar.</div>';form.reportValidity();return}
 updatesInProgress.add(id);button.disabled=true;feedback.innerHTML='<div class="notice">Registrando atualização…</div>';
 await request('/api/items/'+id+'/update','POST',d);
 const saved=await request('/api/items'),entry=saved.find(x=>x.id===id),events=await request('/api/items/'+id+'/events');
 if(!entry||entry.status!==d.status.trim()||entry.action_taken!==d.action_taken.trim()||entry.next_action!==d.next_action.trim()||entry.updated_by!==d.actor.trim()||!events.length||events[0].actor!==d.actor.trim()||events[0].detail!==d.note.trim()+' | Status: '+d.status.trim())throw Error('Não foi possível confirmar a atualização. Consulte o histórico antes de tentar novamente.');
 items=saved;handovers=await request('/api/handovers');$('#filter').value='all';$('#search').value='';render();tab('records');
 toast('Registro #'+id+' atualizado. Exibindo todos os registros com os status atuais.'+(entry.status==='Resolvido'?' Registro resolvido disponível apenas para consulta.':''));
 }catch(err){feedback.innerHTML='<div class="notice error">'+esc(err.message||String(err))+'</div>';toast(err.message||String(err),true)}finally{updatesInProgress.delete(id);button.disabled=false}
}
async function saveCorrection(form){const id=Number(form.dataset.id);if(updatesInProgress.has(id))return;const feedback=form.querySelector('.correction-status'),button=form.querySelector('.save-correction');try{const d=formValues(form);if(!d.note.trim()){feedback.innerHTML='<div class="notice error">Preencha a Nota de Atualização.</div>';form.elements.namedItem('note').focus();return}if(!form.checkValidity()){form.reportValidity();return}updatesInProgress.add(id);button.disabled=true;await request('/api/items/'+id+'/resolved-edit','POST',d);const saved=await request('/api/items'),x=saved.find(i=>i.id===id);if(!x||x.status!=='Resolvido'||x.action_taken!==d.action_taken.trim()||x.next_action!==d.next_action.trim())throw Error('Não foi possível confirmar a correção. Consulte o histórico.');items=saved;handovers=await request('/api/handovers');$('#filter').value='all';$('#search').value='';render();tab('records');toast('Correção salva no registro #'+id+'. Status mantido como Resolvido.')}catch(err){feedback.innerHTML='<div class="notice error">'+esc(err.message)+'</div>'}finally{updatesInProgress.delete(id);button.disabled=false}}
