let assumingShift=false;
async function assumeShift(e){if(e)e.preventDefault();if(assumingShift)return;const form=$('#handoverForm'),button=$('#assumeShift'),feedback=$('#handoverStatus');try{
 const d=formValues(form),missing=[];if(!String(d.outgoing||'').trim())missing.push('Operador que está saindo');if(!String(d.incoming||'').trim())missing.push('Operador que está entrando');
 if(missing.length){feedback.innerHTML='<div class="notice error">Preencha: '+missing.join(' e ')+'.</div>';form.elements.namedItem(!String(d.outgoing||'').trim()?'outgoing':'incoming').focus();return}
 if(!form.checkValidity()){feedback.innerHTML='<div class="notice error">Confira os limites de caracteres dos campos.</div>';form.reportValidity();return}
 assumingShift=true;button.disabled=true;feedback.innerHTML='<div class="notice">Registrando recebimento do turno…</div>';
 const result=await request('/api/handovers','POST',d),saved=await request('/api/handovers'),entry=saved.find(h=>h.id===result.id);
 if(!entry||entry.incoming!==d.incoming.trim()||entry.outgoing!==d.outgoing.trim()||entry.note!==d.note.trim()||JSON.parse(entry.open_ids).length!==result.count)throw Error('Não foi possível confirmar a passagem. Consulte o histórico antes de tentar novamente.');
 items=await request('/api/items');handovers=saved;render();form.reset();feedback.innerHTML='<div class="notice">Passagem #'+entry.id+' registrada em '+esc(fmt(entry.at))+'. '+esc(entry.incoming)+' assumiu o turno de '+esc(entry.outgoing)+'. '+result.count+' pendência(s) aberta(s) vinculada(s). Consulte o histórico abaixo.</div>';toast('Recebimento do turno registrado e conferido.');feedback.scrollIntoView({block:'nearest'});
 }catch(err){feedback.innerHTML='<div class="notice error">'+esc(err.message||String(err))+'</div>';toast(err.message||String(err),true)}finally{assumingShift=false;button.disabled=false}}
