function validateImport(raw){
 if(!raw||!Array.isArray(raw.items)||!Array.isArray(raw.events)||!Array.isArray(raw.handovers))throw Error('Este arquivo não é uma exportação do MOP. Selecione o arquivo .json gerado por Exportar dados.');
 const data=JSON.parse(JSON.stringify(raw)),seen=new Set();
 for(const x of data.items){
  if(!x||!Number.isSafeInteger(x.id)||x.id<1||seen.has(x.id))throw Error('O arquivo contém identificadores de registros inválidos ou repetidos.');seen.add(x.id);
  for(const k of ['subject','description','condo','category','created_by','created_at','updated_at','status'])if(typeof x[k]!=='string')throw Error('Registro #'+x.id+': campo '+k+' ausente ou inválido.');
  if(!['Pendente','Em andamento','Aguardando resposta','Aguardando manutenção','Resolvido'].includes(x.status))throw Error('Registro #'+x.id+': status inválido.');
  for(const k of ['company','reference','source','action_taken','next_action']){if(x[k]==null)x[k]='';if(typeof x[k]!=='string')throw Error('Registro #'+x.id+': campo '+k+' inválido.');}
  for(const k of planningKeys)if(x[k]!=null&&typeof x[k]!=='string')throw Error('Campo de planejamento inválido: '+k);Object.assign(x,planningValues(x,x.category));
  x.updated_by=typeof x.updated_by==='string'?x.updated_by:x.created_by;x.priority=x.priority||'Normal';
  if(!['Normal','Atenção','Urgente'].includes(x.priority))throw Error('Registro #'+x.id+': prioridade inválida.');
 }
 for(const e of data.events){if(!e||!Number.isSafeInteger(e.id)||e.id<1||!seen.has(e.item_id)||!['at','actor','kind','detail'].every(k=>typeof e[k]==='string'))throw Error('Histórico inválido no arquivo. Nenhum dado foi alterado.');}
 for(const h of data.handovers){if(!h||!Number.isSafeInteger(h.id)||h.id<1||!['at','incoming','outgoing','note','open_ids'].every(k=>typeof h[k]==='string'))throw Error('Passagem de turno inválida no arquivo.');if(h.snapshot!=null){if(!Array.isArray(h.snapshot)||!h.snapshot.every(x=>x&&Number.isSafeInteger(x.id)&&['subject','condo','status'].every(k=>typeof x[k]==='string')&&['next_action','assignee','deadline','protocol'].every(k=>x[k]==null||typeof x[k]==='string')))throw Error('Retrato de passagem inválido.');}let ids;try{ids=JSON.parse(h.open_ids)}catch(e){throw Error('Lista de passagem de turno inválida.')}if(!Array.isArray(ids)||!ids.every(Number.isSafeInteger))throw Error('Lista de passagem de turno inválida.');}
 for(const [collection,counter] of [['items','nextItem'],['events','nextEvent'],['handovers','nextHandover']])data[counter]=data[collection].reduce((max,x)=>Math.max(max,x.id+1),1);
 ensureProtocols(data);return data;
}
