const calendarZone='America/Sao_Paulo';
function calendarDate(value){const d=new Date(value);if(Number.isNaN(d.getTime()))return '';const parts=new Intl.DateTimeFormat('en-CA',{timeZone:calendarZone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);const v=Object.fromEntries(parts.map(p=>[p.type,p.value]));return v.year+'-'+v.month+'-'+v.day}
let selectedCalendarDate=calendarDate(new Date()),calendarMonth=selectedCalendarDate.slice(0,7);
function monthGrid(month){const [y,m]=month.split('-').map(Number),first=new Date(Date.UTC(y,m-1,1)),start=new Date(first);start.setUTCDate(1-first.getUTCDay());const total=new Date(Date.UTC(y,m,0)).getUTCDate(),cells=Math.ceil((first.getUTCDay()+total)/7)*7;return Array.from({length:cells},(_,i)=>{const d=new Date(start);d.setUTCDate(start.getUTCDate()+i);return d.toISOString().slice(0,10)})}
function selectedRecords(data){return data.filter(x=>!x.deleted_at&&(!$('#calCondo').value||x.condo===$('#calCondo').value)&&(!$('#calCategory').value||x.category===$('#calCategory').value)&&(!$('#calStatus').value||x.status===$('#calStatus').value))}
function calendarHistoryHtml(events){return events.length?events.map(e=>`<p><small>${esc(new Date(e.at).toLocaleString('pt-BR',{timeZone:calendarZone}))} · ${esc(e.actor)} · ${esc(e.kind)} · ${esc(shiftLabel(e.shift,e.at))}</small><br>${esc(e.detail)}${planningAudit(e)}${e.before&&e.after?`<br><small>Ação anterior: ${esc(e.before.action_taken||'—')}<br>Ação atualizada: ${esc(e.after.action_taken||'—')}<br>Próxima ação anterior: ${esc(e.before.next_action||'—')}<br>Próxima ação atualizada: ${esc(e.after.next_action||'—')}</small>`:''}</p>`).join(''):'<p class="muted">Nenhuma atualização disponível.</p>'}
function renderCalendar(){try{const data=readStore(),records=selectedRecords(data.items),today=calendarDate(new Date());$('#calDate').value=selectedCalendarDate;$('#calMonth').textContent=new Date(calendarMonth+'-15T12:00:00Z').toLocaleDateString('pt-BR',{month:'long',year:'numeric',timeZone:calendarZone});const rc={},hc={};records.forEach(x=>{const d=calendarDate(x.created_at);rc[d]=(rc[d]||0)+1});data.handovers.forEach(x=>{const d=calendarDate(x.at);hc[d]=(hc[d]||0)+1});$('#calGrid').innerHTML=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(d=>'<div class="calendar-weekday">'+d+'</div>').join('')+monthGrid(calendarMonth).map(d=>`<button type="button" class="calendar-day ${d.slice(0,7)!==calendarMonth?'outside':''} ${d===selectedCalendarDate?'selected':''} ${d===today?'today':''}" data-date="${d}" aria-pressed="${d===selectedCalendarDate}" aria-label="${d.split('-').reverse().join('/')} — ${rc[d]||0} registros e ${hc[d]||0} passagens"><b>${Number(d.slice(-2))}</b>${rc[d]?`<small>● ${rc[d]} reg.</small>`:''}${hc[d]?`<small class="turn-count">◆ ${hc[d]} turno(s)</small>`:''}</button>`).join('');const dayRecords=records.filter(x=>calendarDate(x.created_at)===selectedCalendarDate).sort((a,b)=>b.created_at.localeCompare(a.created_at)),dayHandovers=data.handovers.filter(x=>calendarDate(x.at)===selectedCalendarDate).sort((a,b)=>b.at.localeCompare(a.at));$('#calDayTitle').textContent=new Date(selectedCalendarDate+'T12:00:00Z').toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:calendarZone});$('#calRecordCount').textContent=dayRecords.length;$('#calHandoverCount').textContent=dayHandovers.length;
$('#calRecords').innerHTML=dayRecords.length?dayRecords.map(x=>`<div class="item ${x.status==='Resolvido'?'resolved':x.priority==='Urgente'?'urgent':''}"><div class="row"><strong>#${x.id} · ${esc(x.subject)}</strong><span class="tag ${x.status==='Resolvido'?'done':''}">${esc(x.status)}</span></div><p>${esc(x.condo)} · ${esc(x.category)}</p><small>Criado em ${esc(new Date(x.created_at).toLocaleString('pt-BR',{timeZone:calendarZone}))} por ${esc(x.created_by)}</small><details><summary>Ver detalhes e histórico</summary><p>${esc(x.description)}</p><p><b>Empresa:</b> ${esc(x.company||'—')}<br><b>Ação realizada:</b> ${esc(x.action_taken||'—')}<br><b>Próxima ação:</b> ${esc(x.next_action||'—')}</p><div class="calendar-history">${planningSummary(x)}${calendarHistoryHtml(data.events.filter(e=>e.item_id===x.id).reverse())}</div></details></div>`).join(''):'<div class="empty">Nenhum registro criado nesta data com os filtros selecionados.</div>';
$('#calHandovers').innerHTML=dayHandovers.length?dayHandovers.map(h=>`<div class="item"><strong>Passagem #${h.id} · ${esc(new Date(h.at).toLocaleTimeString('pt-BR',{timeZone:calendarZone}))}</strong><p>${esc(h.outgoing)} → ${esc(h.incoming)}</p><details><summary>Ver detalhes da passagem</summary><p>${esc(h.note||'Sem observação')}</p><p><b>Pendências no recebimento:</b> ${JSON.parse(h.open_ids).length}</p>${snapshotHistory(h)}</details></div>`).join(''):'<div class="empty">Nenhuma passagem confirmada nesta data.</div>';
}catch(e){toast('Não foi possível abrir o calendário: '+e.message,true)}}
function changeCalendarMonth(delta){const [y,m]=calendarMonth.split('-').map(Number);calendarMonth=new Date(Date.UTC(y,m-1+delta,1)).toISOString().slice(0,7);selectedCalendarDate=calendarMonth+'-01';renderCalendar()}
$('#calPrev').onclick=()=>changeCalendarMonth(-1);$('#calNext').onclick=()=>changeCalendarMonth(1);$('#calToday').onclick=()=>{selectedCalendarDate=calendarDate(new Date());calendarMonth=selectedCalendarDate.slice(0,7);renderCalendar()};$('#calDate').onchange=e=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(e.target.value))return;selectedCalendarDate=e.target.value;calendarMonth=selectedCalendarDate.slice(0,7);renderCalendar()};$('#calGrid').onclick=e=>{const b=e.target.closest('[data-date]');if(!b)return;selectedCalendarDate=b.dataset.date;calendarMonth=selectedCalendarDate.slice(0,7);renderCalendar()};
$('#calCondo').innerHTML+=$('#newForm select[name="condo"]').innerHTML.replace('<option value="">Selecione</option>','');$('#calCategory').innerHTML+=categories.map(x=>'<option>'+esc(x)+'</option>').join('');$('#calStatus').innerHTML+=['Pendente','Em andamento','Aguardando resposta','Aguardando manutenção','Resolvido'].map(x=>'<option>'+x+'</option>').join('');['#calCondo','#calCategory','#calStatus'].forEach(k=>$(k).onchange=renderCalendar);
function shiftLabel(saved,timestamp){try{return MOPShift.label(saved||MOPShift.at(timestamp));}catch{return 'Turno não disponível';}}
let displayedShiftId,shiftTimer,mopReady=false;
function updateShiftIndicator(now=new Date()){
 const shift=MOPShift.at(now),seconds=Math.max(0,Math.ceil((Date.parse(shift.end_at)-now.getTime())/1000));
 $('#currentShift').textContent='Turno atual: '+MOPShift.label(shift);
 $('#clock').textContent=now.toLocaleString('pt-BR',{timeZone:MOPShift.zone})+' · São Paulo';
 $('#shiftRemaining').textContent='Restam '+[Math.floor(seconds/3600),Math.floor(seconds%3600/60),seconds%60].map(n=>String(n).padStart(2,'0')).join(':');
 const status=$('#shiftReceipt');
 try{const confirmed=MOPShift.received(readStore().handovers,shift);status.textContent=confirmed?'Recebimento confirmado':'Troca de turno pendente';status.classList.toggle('pending',!confirmed);}
 catch{status.textContent='Não foi possível consultar o recebimento';status.classList.add('pending');}
 const changed=displayedShiftId!==shift.id;displayedShiftId=shift.id;return changed;
}
function tickShift(){
 if(!mopReady)return;
 clearTimeout(shiftTimer);
 try{if(updateShiftIndicator()&&!$('#overview').classList.contains('hidden'))renderDeadlines();}
 catch(e){toast(e.message,true);}
 finally{shiftTimer=setTimeout(tickShift,1000-Date.now()%1000);}
}
window.addEventListener('focus',tickShift);
window.addEventListener('pageshow',tickShift);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tickShift();});
if(window.mopDesktop?.onResume)window.mopDesktop.onResume(tickShift);
window.initializeMop=async()=>{
 mopReady=false;clearTimeout(shiftTimer);
 checkStorage(true);await refresh(true);
 mopReady=true;tickShift();
};
window.lockMop=()=>{mopReady=false;clearTimeout(shiftTimer);clearTimeout(toastTimer);items=[];handovers=[];};

document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();tab(b.dataset.go)}));
$('#refreshRecords').onclick=()=>refresh();
$('#backupNow').onclick=async()=>{try{if(await window.mopDesktop.exportData())toast('Backup salvo com sucesso.')}catch(e){toast(e.message,true)}};
$('#openData').onclick=async()=>{try{await window.mopDesktop.openData()}catch(e){toast(e.message,true)}};
